import base64, zlib, json, hashlib, os, sys
sys.path.insert(0, os.getcwd())
D = json.loads(zlib.decompress(base64.b64decode("")).decode("utf-8"))
norm = lambda b: b.decode("utf-8", errors="replace").replace("\r\n", "\n").lstrip("\ufeff")
print("=== B12.1 CHECK (read-only) ===")
ok_all = True
print("\n1. NEW / REPLACED FILES -- exact fingerprints (line endings ignored)")
for p, want in D["fp"].items():
    got = hashlib.sha256(norm(open(p, "rb").read()).encode("utf-8")).hexdigest().upper() if os.path.exists(p) else "MISSING"
    ok = got == want; ok_all &= ok
    print("   %-44s %s" % (p, "OK" if ok else "WRONG (" + got[:16] + " -- expected " + want[:16] + ")"))
print("\n2. THE %d EDITS -- each present exactly once, the old text gone where it was replaced" % len(D["edits"]))
for e in D["edits"]:
    s = norm(open(e["path"], "rb").read()) if os.path.exists(e["path"]) else ""
    ok = s.count(e["text"] + e["find"]) == 1 if e["action"] == "INSERT_BEFORE" else (s.count(e["text"]) == 1 and (e["find"] in e["text"] or s.count(e["find"]) == 0))
    ok_all &= ok
    print("   %-3s %-40s %-58s %s" % (e["seg"], e["path"], e["title"][:58], "OK" if ok else "NOT FOUND AS WRITTEN"))
print("\n3. YOUR RULES -- read the way the engine reads them (rule 12)")
from src.execution.ns_engine import market_settings
M = ["GOLD", "USOIL", "USTEC", "BTC", "EURUSD", "GBPAUD", "JP225", "EURJPY", "SILVER", "AUDJPY"]
def want(a):
    return {"quality_lines": True, "break_rule": "big_or_1h_hold", "big_break_atr": 0.25, "reversal_rule": "vote2" if a == "BTC" else "brain4",
            "room_required": False, "room_atr": 1.0}
for f in [x for x in ("config/config.json", "config/config.template.json", "config/config.prod.json") if os.path.exists(x)]:
    pc = json.load(open(f, encoding="utf-8-sig")).get("phase_config", {})
    bad = [a for a in M if any((market_settings(a, pc) or {}).get(k) != v for k, v in want(a).items())]
    ok_all &= not bad
    print("   %-30s your rules on all 10 markets (BTC 2 of 3): %s" % (f, "YES" if not bad else "NO -- " + ", ".join(bad)))
print("\n4. SATURDAY'S RESEARCH runs the same rules")
import importlib.util
spec = importlib.util.spec_from_file_location("at_chk", os.path.join("tools", "all_tests.py"))
at = importlib.util.module_from_spec(spec); sys.modules["at_chk"] = at; spec.loader.exec_module(at)
R = at._live_rules(); bad = [a for a in M if {k: R.get(a, {}).get(k) for k in want(a)} != want(a)]; ok_all &= not bad
print("   research rules: %s" % ("the same as the engine's for all 10 markets" if not bad else "DIFFERENT for " + ", ".join(bad)))
print("\nRESULT: %s" % ("ALL OK -- B12.1 is in place" if ok_all else "SOMETHING IS WRONG -- stop and send this to Claude"))
